<?php
if(!$PCC->tableExists('catalog_items')):?><section class="pcc-panel"><div class="pcc-empty"><i class="fas fa-shopping-bag"></i><strong>Catalogue indisponible</strong><span>catalog_items n’existe pas.</span></div></section><?php return;endif;
$q=trim((string)($_GET['q']??''));$state=(string)($_GET['active']??'');$hasName=$PCC->columnExists('catalog_items','catalog_name');$hasPage=$PCC->columnExists('catalog_items','page_id');$hasItems=$PCC->columnExists('catalog_items','item_ids');$hasAmount=$PCC->columnExists('catalog_items','amount');$hasPixels=$PCC->columnExists('catalog_items','cost_pixels');$hasDiamonds=$PCC->columnExists('catalog_items','cost_diamonds');
$cols='id,cost_credits,offer_active'.($hasName?',catalog_name':',NULL catalog_name').($hasPage?',page_id':',NULL page_id').($hasItems?',item_ids':',NULL item_ids').($hasAmount?',amount':',NULL amount').($hasPixels?',cost_pixels':',NULL cost_pixels').($hasDiamonds?',cost_diamonds':',NULL cost_diamonds');$where=array('1=1');$types='';$params=array();if($q!==''){$bits=array('CAST(id AS CHAR)=?');$types='s';$params=array($q);$like='%'.mb_substr($q,0,64).'%';if($hasName){$bits[]='catalog_name LIKE ?';$types.='s';$params[]=$like;}if($hasItems){$bits[]='item_ids LIKE ?';$types.='s';$params[]=$like;}$where[]='('.implode(' OR ',$bits).')';}if($state==='0'||$state==='1'){$where[]='offer_active=?';$types.='i';$params[]=(int)$state;}$rows=$DB->PreparedAll('SELECT '.$cols.' FROM catalog_items WHERE '.implode(' AND ',$where).' ORDER BY id DESC LIMIT 500',$types,$params);
?>
<section class="pcc-panel"><form class="pcc-filterbar"><input type="hidden" name="page" value="catalogue"><div class="pcc-search-field"><i class="fas fa-search"></i><input name="q" value="<?php echo $h($q);?>" placeholder="Nom, ID offre ou item ID…"></div><select class="pcc-select-compact" name="active"><option value="">Tous statuts</option><option value="1" <?php echo $state==='1'?'selected':'';?>>Actives</option><option value="0" <?php echo $state==='0'?'selected':'';?>>Inactives</option></select><button class="pcc-button secondary">Filtrer</button><span class="pcc-filter-count"><?php echo $number(count($rows));?> offre(s)</span></form><div class="pcc-table-wrap"><table class="pcc-table pcc-table-dense"><thead><tr><th>ID</th><th>Nom</th><?php if($hasPage):?><th>Page</th><?php endif;?><?php if($hasItems):?><th>Item IDs</th><?php endif;?><th>Crédits</th><?php if($hasPixels):?><th>Pixels</th><?php endif;?><?php if($hasDiamonds):?><th>Diamants</th><?php endif;?><?php if($hasAmount):?><th>Quantité</th><?php endif;?><th>État</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="9"><div class="pcc-empty compact"><strong>Aucune offre trouvée</strong></div></td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td>#<?php echo (int)$r['id'];?></td><td><?php echo $r['catalog_name']?$h($r['catalog_name']):'—';?></td><?php if($hasPage):?><td><?php echo (int)$r['page_id'];?></td><?php endif;?><?php if($hasItems):?><td><code><?php echo $h($r['item_ids']);?></code></td><?php endif;?><td><strong><?php echo $number($r['cost_credits']);?></strong></td><?php if($hasPixels):?><td><?php echo $number($r['cost_pixels']);?></td><?php endif;?><?php if($hasDiamonds):?><td><?php echo $number($r['cost_diamonds']);?></td><?php endif;?><?php if($hasAmount):?><td><?php echo $number($r['amount']);?></td><?php endif;?><td><span class="pcc-badge <?php echo !empty($r['offer_active'])?'success':'warning';?>"><?php echo !empty($r['offer_active'])?'ACTIVE':'INACTIVE';?></span></td></tr><?php endforeach;?></tbody></table></div></section>
<?php if($PCC->can('catalog.manage')):?><section class="pcc-panel"><div class="pcc-panel-head"><div><h2>Modifier une offre</h2><p>Outil historique conservé, mais intégré à la page Catalogue.</p></div></div><form class="pcc-form pcc-form-horizontal" method="post" data-confirm-form data-confirm-title="Modifier cette offre catalogue ?" data-confirm-message="Prix et statut seront enregistrés dans l’audit."><input type="hidden" name="csrf" value="<?php echo $h($PCC->csrfToken());?>"><input type="hidden" name="action_nonce" value="<?php echo $h($PCC->issueNonce());?>"><input type="hidden" name="action" value="catalogue_update"><input type="hidden" name="return_page" value="catalogue"><label><span>ID offre</span><input type="number" name="offer_id" min="1" required></label><label><span>Prix crédits</span><input type="number" name="price" min="0" max="999999" required></label><label class="pcc-check"><input type="checkbox" name="active" value="1" checked><span>Offre active</span></label><label class="wide"><span>Raison</span><input name="reason" minlength="3" maxlength="500" required></label><button class="pcc-button primary" <?php echo !$PCC->auditReady()?'disabled':'';?>>Enregistrer</button></form></section><?php endif;?>
